    workers.append({'id':task,'title':task,'role':'worker','process':'task-batch-execution','objective':f'Implement the bounded repair brief {brief}', 'execution_mode':'implementation','writer':True,'model':'gpt-5.6-luna','reasoning_effort':'high','allowed_files':public+[f'{REL}/{task}/**',f'.pf/tmp/{task}/**'],'allowed_read_files':public+['src/processforge_core/**','tools/pf_runtime/**','tools/processforge.py','tools/*smoke*.py','tools/*helpers*.py','docs/concepts/**',f'{REL}/**','.pf/artifacts/codebase-audit-20260910/**','.pf/AGENTS.md','.pf/contexts/**'],'forbidden_files':['VERSION','CHANGELOG.md','checksums/**','.pf/artifacts/codebase-audit-20260910/**','.pf/process-forge.yaml'], 'required_sources':[brief,f'{REL}/design.md'],'required_outputs':[{'id':task+'-report','path':f'{REL}/{task}/report.md','type':'markdown','required':True}],'expected_report_artifact':f'{REL}/{task}/report.md','runtime_driver':'codex-exec','depends_on':[],'allow_subagents':False,'worker_may_rebuild_context':False})
