(OUT/'wave1-plan.yaml').write_text(json.dumps(plan,indent=2),encoding='utf-8')
tracked=subprocess.check_output(['git','ls-files'],cwd=ROOT,text=True).splitlines()
hashes={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in tracked if not p.startswith('.pf/') and (ROOT/p).is_file()}
(OUT/'baseline.json').write_text(json.dumps({'head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'hashes':hashes},indent=2),encoding='utf-8')
print('Prepared three disjoint workers and baseline',len(hashes))
